import { Table, Input, Button } from '@dreadnought/ui/react';
type Person = { key: number; name: string };
const example = <Table<Person> pagination={false} dataSource={[{ key: 1, name: 'Anna' }]} columns={[{ key: 'name', title: 'Name', dataIndex: 'name', onFilter: (value, row) => row.name.includes(String(value)), filterDropdown: ({ selectedKeys, setSelectedKeys, confirm, clearFilters }) => <><Input aria-label="Name filter" value={String(selectedKeys[0] ?? '')} onChange={event => setSelectedKeys(event.target.value ? [event.target.value] : [])} /><Button type="button" onClick={() => confirm()}>Apply</Button><Button type="button" onClick={() => clearFilters()}>Reset</Button></> }]} />;

import { Table } from '@dreadnought/ui/react';
type Person = { key: number; name: string };
const example = <Table<Person> processing="manual" loading pagination={{ current: 2, pageSize: 2, total: 10 }} dataSource={[{ key: 3, name: 'Anna' }]} columns={[{ key: 'name', title: 'Name', dataIndex: 'name', sorter: true }]} slotProps={{ loader: { label: 'Loading results' } }} onChange={(page, filters, _sorter, extra) => { console.log(page, filters, extra.sorters); }} />;

import { Table } from '@dreadnought/ui/react';
type Person = { key: number; team: string; age: number };
const example = <Table<Person> pagination={false} dataSource={[{ key: 1, team: 'Design', age: 29 }]} columns={[{ key: 'team', title: 'Team', dataIndex: 'team', sorter: { compare: (a, b) => a.team.localeCompare(b.team), multiple: 2 } }, { key: 'age', title: 'Age', dataIndex: 'age', sorter: { compare: (a, b) => a.age - b.age, multiple: 1 } }]} onChange={(_page, _filters, _sorter, extra) => { console.log(extra.sorters); }} />;

import { Table } from '@dreadnought/ui/react';
